package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;import java.util.*;
public final class PreparedSceneTest {
 static void check(boolean value){if(!value)throw new AssertionError("Prepared source changed");}
 public static void main(String[] args)throws Exception{int scenes=0,rows=0;Path dir=Paths.get(args[0]);try(DirectoryStream<Path> paths=Files.newDirectoryStream(dir,"source-race-background-*.nrb")){for(Path path:paths){byte[] raw=Files.readAllBytes(path);NativeBackgroundScene background=new NativeBackgroundScene(raw);NativePreparedScene p=new NativePreparedScene(background);check(p.background==background&&p.scene==background.sky.scene&&p.composition.belongsTo(p.scene));check(!p.composition.belongsTo(new NativeBackgroundScene(raw).sky.scene));ByteBuffer expected=background.exactRgba(),palette=NativeHistoricalPalette.rgba(p.scene);NativeHudFrame hud=new NativeHudFrame(p.scene);check(p.backgroundRgba().equals(expected)&&p.paletteRgba().equals(palette)&&p.hud.colors().equals(hud.colors())&&p.hud.metadata().equals(hud.metadata()));for(int y=0;y<160;y++){check(Arrays.equals(p.hud.parameters(y),hud.parameters(y)));rows++;}check(p.backgroundRgba().isReadOnly()&&p.paletteRgba().isReadOnly());try{p.backgroundRgba().put(0,(byte)7);throw new AssertionError("Writable cached RGBA");}catch(ReadOnlyBufferException required){}p.backgroundRgba().position(153600);p.paletteRgba().position(163840);Arrays.fill(raw,(byte)0);check(p.backgroundRgba().position()==0&&p.paletteRgba().position()==0&&p.backgroundRgba().equals(expected)&&p.paletteRgba().equals(palette));scenes++;}}check(scenes==9&&rows==1440);System.out.println("PASS_PREPARED_SCENE scenes=9 hud_parameter_rows=1440 source_buffers_equal=true read_only_and_position_isolated=true exact_scene_binding=true");}
}
